import torch
import torch.nn.functional as F


def gen_inputs(ctx, device):
    result = {}
    for name in ("query", "key", "value"):
        shape = tuple(ctx[f"{name}__shape"])
        dtype = getattr(torch, ctx[f"{name}__dtype"])
        result[name] = torch.randn(shape, dtype=dtype, device=device).uniform_(-0.1, 0.1)
    return result


def run(query, key, value, attn_bias, dropout_p, is_causal, return_debug_mask, scale):
    output = F.scaled_dot_product_attention(
        query,
        key,
        value,
        attn_mask=attn_bias,
        dropout_p=dropout_p,
        is_causal=is_causal,
        scale=scale,
    )
    batch = query.shape[0]
    seq_len_q = query.shape[2]
    seq_len_k = key.shape[2]
    logsumexp = torch.empty(
        (batch, query.shape[1], seq_len_q), dtype=torch.float32, device=query.device
    )
    cum_seq_q = torch.tensor(
        [0, seq_len_q] * batch, dtype=torch.int32, device=query.device
    ).reshape(batch, 2)
    cum_seq_k = torch.tensor(
        [0, seq_len_k] * batch, dtype=torch.int32, device=key.device
    ).reshape(batch, 2)
    philox_seed = torch.zeros(1, dtype=torch.int64, device=query.device)
    philox_offset = torch.zeros(1, dtype=torch.int64, device=query.device)
    debug_attn_mask = torch.empty(0, dtype=query.dtype, device=query.device)
    return (
        output,
        logsumexp,
        cum_seq_q,
        cum_seq_k,
        seq_len_q,
        seq_len_k,
        philox_seed,
        philox_offset,
        debug_attn_mask,
    )


def valid(ref_outputs, sol_outputs, inputs, ctx):
    if len(sol_outputs) != 9:
        return {"passed": False, "message": "expected 9 outputs", "metrics": {}}
    query, key = inputs[0], inputs[1]
    dtype = query.dtype
    ref = ref_outputs[0].to(dtype)
    sol = sol_outputs[0]
    rtol = {
        torch.float16: 1e-3,
        torch.bfloat16: 0.016,
        torch.float32: 1.3e-6,
        torch.float64: 1e-7,
    }.get(dtype, 1.3e-6)
    try:
        torch.testing.assert_close(sol, ref, rtol=rtol, atol=1e-4)
    except AssertionError as exc:
        return {"passed": False, "message": str(exc), "metrics": {}}
    batch = query.shape[0]
    if tuple(sol_outputs[2].shape) != (batch, 2):
        return {"passed": False, "message": "cum_seq_q shape mismatch", "metrics": {}}
    if tuple(sol_outputs[3].shape) != (batch, 2):
        return {"passed": False, "message": "cum_seq_k shape mismatch", "metrics": {}}
    if sol_outputs[4] != query.shape[2] or sol_outputs[5] != key.shape[2]:
        return {"passed": False, "message": "max sequence length mismatch", "metrics": {}}
    if tuple(sol_outputs[6].shape) != (1,) or tuple(sol_outputs[7].shape) != (1,):
        return {"passed": False, "message": "philox state shape mismatch", "metrics": {}}
    return {"passed": True, "message": "", "metrics": {}}
